mapper.select:
SELECT r.ar_id, r.company_id, r.ar_no, r.source_module, r.source_type, r.source_id, r.source_key, r.partner_id, r.partner_name, r.customer_id, r.ar_date, r.period, r.amount_excl_tax, r.tax_amount, r.total_amount, r.received_amount, r.bad_debt_amount, r.tax_rate, r.invoice_no, r.invoice_code, r.invoice_date, r.due_date, r.payment_days, r.status, r.dept_id, r.user_id, r.create_by, r.create_time, r.update_by, r.update_time, r.remark FROM fin_ar_order r
AND r.ar_no LIKE CONCAT('%', #{arNo}, '%')
AND r.partner_name LIKE CONCAT('%', #{partnerName}, '%')
AND r.period = #{period}
AND r.status = #{status}
AND r.ar_date >= #{params.beginArDate}
AND r.ar_date <= #{params.endArDate}
AND r.del_flag = '0'
AND ${params.dataScope}
ORDER BY r.ar_date DESC, r.ar_id DESC


WHERE source_module = #{sourceModule}
  AND source_type   = #{sourceType}
  AND source_id     = #{sourceId}
  AND del_flag      = '0'
LIMIT 1

mapper.update:
UPDATE fin_ar_order
partner_id = #{partnerId}, partner_name = #{partnerName}, ar_date = #{arDate}, period = #{period}, due_date = #{dueDate}, payment_days = #{paymentDays}, status = #{status}, bad_debt_amount = #{badDebtAmount}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
WHERE ar_id = #{arId}

UPDATE fin_ar_order SET del_flag = '2', update_time = sysdate() WHERE ar_id IN
#{id}
AND status != 'SETTLED'
